"use client";

import { useEffect, useState } from "react";
import { apiGet } from "@/lib/api-client";
import { useAppStore } from "@/store/app-store";
import { PageHeader } from "@/components/app/page-header";
import { StatusBadge } from "@/components/app/status-badge";
import { EmptyState, LoadingState, ErrorState } from "@/components/app/empty-state";
import { Input } from "@/components/ui/input";
import { ClipboardCheck, Search, Calendar, ChevronRight } from "lucide-react";
import { formatDate, inspectionStatusLabel } from "@/lib/constants";

interface InspectionRecord {
  inspectionId: string;
  requestId: string;
  horseId: string;
  horseName: string;
  agencyName: string;
  status: string;
  remarks: string | null;
  updatedAt: string;
}

export function InspectionList() {
  const { navigate } = useAppStore();
  const [inspections, setInspections] = useState<InspectionRecord[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [search, setSearch] = useState("");

  useEffect(() => {
    (async () => {
      try { setInspections(await apiGet<InspectionRecord[]>("/inspections")); }
      catch (e) { setError(e instanceof Error ? e.message : "Không thể tải hồ sơ kiểm định."); }
      finally { setLoading(false); }
    })();
  }, []);

  if (loading) return <LoadingState />;
  if (error) return <ErrorState message={error} />;

  const filtered = inspections.filter((inspection) =>
    !search ||
    inspection.horseName.toLowerCase().includes(search.toLowerCase()) ||
    inspection.agencyName.toLowerCase().includes(search.toLowerCase())
  );

  return (
    <div className="space-y-6">
      <PageHeader title="Hồ sơ kiểm định" description="Các bản ghi kiểm định do backend cung cấp; chưa bao gồm quy trình review hồ sơ pháp lý." icon={<ClipboardCheck className="h-5 w-5" />}
        actions={<div className="relative w-full sm:w-64"><Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" /><Input value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Tìm ngựa / cơ quan..." className="pl-9" /></div>}
      />
      {filtered.length === 0 ? (
        <EmptyState icon={<ClipboardCheck className="h-6 w-6" />} title="Không có bản ghi kiểm định" />
      ) : (
        <div className="space-y-3">
          {filtered.map((inspection) => (
            <button key={inspection.inspectionId} onClick={() => navigate("request-detail", { id: inspection.requestId })} className="flex w-full items-center gap-4 rounded-xl border border-border bg-card p-4 text-left transition-all hover:border-primary/40 hover:shadow-md">
              <div className="flex h-12 w-12 shrink-0 items-center justify-center rounded-xl bg-primary/10 text-primary"><ClipboardCheck className="h-6 w-6" /></div>
              <div className="min-w-0 flex-1">
                <p className="truncate text-sm font-semibold">{inspection.horseName} · {inspection.agencyName}</p>
                <div className="mt-1 flex flex-wrap items-center gap-x-4 gap-y-1 text-xs text-muted-foreground">
                  <span>Yêu cầu #{inspection.requestId.slice(-8)}</span>
                  <span className="flex items-center gap-1"><Calendar className="h-3 w-3" />{formatDate(inspection.updatedAt)}</span>
                  {inspection.remarks && <span>{inspection.remarks}</span>}
                </div>
              </div>
              <StatusBadge status={inspectionStatusLabel(inspection.status)} />
              <ChevronRight className="h-4 w-4 text-muted-foreground" />
            </button>
          ))}
        </div>
      )}
    </div>
  );
}
