"use client";

import { useAppStore } from "@/store/app-store";
import { CustomerDashboard } from "./customer/customer-dashboard";
import { HorseList } from "./customer/horse-list";
import { HorseDetail } from "./customer/horse-detail";
import { RequestList } from "./customer/request-list";
import { RequestDetail } from "./customer/request-detail";
import { InspectionList } from "./specialist/inspection-list";
import { ApprovalList } from "./manager/approval-list";
import { PlanList } from "./coordinator/plan-list";
import { TransportPlanDetail } from "./coordinator/transport-plan-detail";
import { TransportPlanCreate } from "./coordinator/transport-plan-create";
import { StaffView } from "./manager/staff-view";
import { FleetView } from "./coordinator/fleet-view";
import { NotificationsView } from "./shared/notifications-view";
import { InvoiceList } from "./shared/invoice-list";
import { InvoiceDetail } from "./shared/invoice-detail";
import { BackendUnavailableView } from "./shared/backend-unavailable-view";

export function ViewRouter() {
  const { user, view, navigate } = useAppStore();

  if (!user) return null;
  const role = user.roleId;

  // Dashboard dispatch
  if (view === "dashboard") {
    switch (role) {
      case "CUSTOMER": return <CustomerDashboard />;
      default: return <BackendUnavailableView title="Dashboard" endpoint="/api/dashboard" description="Backend hiện chưa có API tổng hợp dashboard theo vai trò." />;
    }
  }

  // Shared views
  if (view === "notifications") return <NotificationsView />;
  if (view === "trips" || view === "trip-detail") {
    return <BackendUnavailableView title="Chuyến vận chuyển" endpoint="/api/trips/**" description="Không ánh xạ chuyến vận chuyển sang transport plans vì hai API không có cùng mô hình nghiệp vụ." />;
  }
  if (view === "request-detail") return <RequestDetail />;
  if (view === "horse-detail") return <HorseDetail />;

  // Customer views
  if (view === "horses") return <HorseList />;
  if (view === "requests") return <RequestList />;
  if (view === "request-create") {
    return <BackendUnavailableView title="Tạo yêu cầu vận chuyển" endpoint="/api/transport-requests/{id}/options, /submit và upload hồ sơ yêu cầu" description="Backend chỉ có API tạo yêu cầu bằng JSON; wizard hiện yêu cầu tạo bản nháp, báo giá và hồ sơ đính kèm nên chưa thể gửi an toàn." />;
  }

  // Specialist views
  if (view === "inspections") return <InspectionList />;
  if (view === "inspection-detail") return <RequestDetail />; // specialist reviews request detail
  if (view === "compliance") return <InspectionList />;

  // Manager views
  if (view === "approvals") return <ApprovalList />;
  if (view === "approval-detail") return <RequestDetail />;
  if (view === "staff") return <StaffView />;

  // Coordinator views
  if (view === "plans") return <PlanList />;
  if (view === "plan-create") return <TransportPlanCreate />;
  if (view === "plan-detail") return <TransportPlanDetail />;
  if (view === "fleet") return <FleetView />;

  // Invoice & Payment views (customer + manager)
  if (view === "invoices") return <InvoiceList />;
  if (view === "invoice-detail") return <InvoiceDetail />;

  // Recovery Dashboard (customer)
  if (view === "recovery-dashboard") {
    return <BackendUnavailableView title="Theo dõi hồi phục" endpoint="/api/recovery-dashboard" description="Backend chưa có API tổng hợp recovery dashboard." />;
  }

  // Fallback
  navigate("dashboard");
  return null;
}
