"use client";

import { useCallback, useEffect, useState } from "react";
import { apiGet } from "@/lib/api-client";
import { useAppStore } from "@/store/app-store";
import { PageHeader } from "@/components/app/page-header";
import { StatusBadge } from "@/components/app/status-badge";
import { ErrorState, LoadingState, EmptyState } from "@/components/app/empty-state";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { ArrowLeft, MapPin, Route } from "lucide-react";
import { formatDateTime } from "@/lib/constants";

interface TransportPlan {
  planId: string;
  requestId: string;
  routeDetails: string | null;
  departureTime: string;
  arrivalTime: string;
  status: string;
  coordinatorName: string | null;
}

interface RouteStop {
  stopId: string;
  sequenceNo: number;
  locationName: string | null;
  stopName: string | null;
  stopType: string;
  plannedArrivalTime: string | null;
  plannedDepartureTime: string | null;
  notes: string | null;
}

export function TransportPlanDetail() {
  const { params, navigate } = useAppStore();
  const [plan, setPlan] = useState<TransportPlan | null>(null);
  const [stops, setStops] = useState<RouteStop[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [stopsError, setStopsError] = useState("");

  const load = useCallback(async () => {
    setLoading(true);
    setError("");
    setStopsError("");
    try {
      const planData = await apiGet<TransportPlan>(`/transport-plans/${params.id}`);
      setPlan(planData);
      try {
        setStops(await apiGet<RouteStop[]>(`/transport-plans/${params.id}/stops`));
      } catch (e) {
        setStopsError(e instanceof Error ? e.message : "Không thể tải các điểm dừng.");
      }
    } catch (e) {
      setError(e instanceof Error ? e.message : "Không thể tải kế hoạch vận chuyển.");
    } finally {
      setLoading(false);
    }
  }, [params.id]);

  useEffect(() => { void Promise.resolve().then(load); }, [load]);

  if (loading) return <LoadingState />;
  if (error) return <ErrorState message={error} onRetry={() => void load()} />;
  if (!plan) return <ErrorState message="Không tìm thấy kế hoạch vận chuyển." />;

  return (
    <div className="space-y-6">
      <PageHeader
        title={`Kế hoạch #${plan.planId.slice(-8)}`}
        description={plan.routeDetails || `Yêu cầu #${plan.requestId}`}
        icon={<Route className="h-5 w-5" />}
        actions={
          <div className="flex items-center gap-2">
            <StatusBadge status={plan.status} />
            <Button variant="outline" size="sm" onClick={() => navigate("plans")} className="gap-2">
              <ArrowLeft className="h-4 w-4" /> Quay lại
            </Button>
          </div>
        }
      />

      <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
        <Card><CardContent className="p-4"><p className="text-xs text-muted-foreground">Yêu cầu</p><p className="mt-1 break-all text-sm font-medium">{plan.requestId}</p></CardContent></Card>
        <Card><CardContent className="p-4"><p className="text-xs text-muted-foreground">Khởi hành</p><p className="mt-1 text-sm font-medium">{formatDateTime(plan.departureTime)}</p></CardContent></Card>
        <Card><CardContent className="p-4"><p className="text-xs text-muted-foreground">Đến nơi</p><p className="mt-1 text-sm font-medium">{formatDateTime(plan.arrivalTime)}</p></CardContent></Card>
        <Card><CardContent className="p-4"><p className="text-xs text-muted-foreground">Điều phối viên</p><p className="mt-1 text-sm font-medium">{plan.coordinatorName || "—"}</p></CardContent></Card>
      </div>

      <Card>
        <CardHeader><CardTitle className="flex items-center gap-2 text-base"><MapPin className="h-4 w-4" /> Điểm dừng</CardTitle></CardHeader>
        <CardContent className="space-y-3">
          {stopsError && <p role="alert" className="text-sm text-destructive">{stopsError}</p>}
          {!stopsError && stops.length === 0 && <EmptyState icon={<MapPin className="h-5 w-5" />} title="Chưa có điểm dừng" />}
          {stops.map((stop) => (
            <div key={stop.stopId} className="rounded-lg border border-border p-3">
              <div className="flex flex-wrap items-center justify-between gap-2">
                <p className="text-sm font-medium">{stop.sequenceNo}. {stop.locationName || stop.stopName || "Điểm dừng"}</p>
                <StatusBadge status={stop.stopType} />
              </div>
              <p className="mt-1 text-xs text-muted-foreground">
                Dự kiến: {stop.plannedArrivalTime ? formatDateTime(stop.plannedArrivalTime) : "—"} – {stop.plannedDepartureTime ? formatDateTime(stop.plannedDepartureTime) : "—"}
              </p>
              {stop.notes && <p className="mt-1 text-sm text-muted-foreground">{stop.notes}</p>}
            </div>
          ))}
          <p className="text-xs text-muted-foreground">
            Phân công tài sản/nhân sự và kiểm tra readiness chưa có API tương đương cho transport plan.
          </p>
        </CardContent>
      </Card>
    </div>
  );
}
