"use client";

import { useEffect, useState } from "react";
import { apiGet, apiPost } from "@/lib/api-client";
import { useAppStore } from "@/store/app-store";
import { useToast } from "@/hooks/use-toast";
import { PageHeader } from "@/components/app/page-header";
import { StatusBadge } from "@/components/app/status-badge";
import { EmptyState, LoadingState, ErrorState } from "@/components/app/empty-state";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Avatar, AvatarFallback } from "@/components/ui/avatar";
import { Users, Phone, Mail, Building2, UserPlus, Loader2, X } from "lucide-react";
import { ROLE_LABELS } from "@/lib/constants";

interface StaffUser {
  userId: string;
  name: string;
  email: string;
  phoneNumber: string | null;
  organizationName: string | null;
  roleId: string;
}

const STAFF_ROLES = [
  { id: "LOGISTICS_MANAGER", label: "Quản lý Logistics" },
  { id: "TRANSPORT_SPECIALIST", label: "Chuyên viên Thủ tục & Kiểm dịch" },
  { id: "FLEET_COORDINATOR", label: "Điều phối viên Đội xe & Lộ trình" },
  { id: "DRIVER_ESCORT", label: "Tài xế / Nhân viên đi kèm" },
];

export function StaffView() {
  const { toast } = useToast();
  const [users, setUsers] = useState<StaffUser[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [showCreate, setShowCreate] = useState(false);
  const [createLoading, setCreateLoading] = useState(false);
  const [createForm, setCreateForm] = useState({ name: "", email: "", phone: "", roleId: "DRIVER_ESCORT", password: "" });

  const load = async () => {
    try { setUsers(await apiGet<StaffUser[]>("/users")); }
    catch (e) { setError(e instanceof Error ? e.message : "Không thể tải danh sách nhân viên."); }
    finally { setLoading(false); }
  };

  useEffect(() => { void Promise.resolve().then(load); }, []);

  const handleCreate = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!createForm.name || !createForm.email || !createForm.phone || !createForm.password) {
      toast({ title: "Thiếu thông tin", description: "Vui lòng nhập họ tên, email, số điện thoại và mật khẩu.", variant: "destructive" });
      return;
    }
    setCreateLoading(true);
    try {
      await apiPost("/users", createForm);
      toast({ title: "Tạo tài khoản thành công", description: `Đã tạo tài khoản ${ROLE_LABELS[createForm.roleId]} cho ${createForm.name}.` });
      setShowCreate(false);
      setCreateForm({ name: "", email: "", phone: "", roleId: "DRIVER_ESCORT", password: "" });
      await load();
    } catch (err) {
      toast({ title: "Tạo tài khoản thất bại", description: err instanceof Error ? err.message : "Không thể tạo tài khoản.", variant: "destructive" });
    } finally {
      setCreateLoading(false);
    }
  };

  if (loading) return <LoadingState />;
  if (error) return <ErrorState message={error} />;

  const byRole: Record<string, StaffUser[]> = {};
  users.forEach((u) => { (byRole[u.roleId] = byRole[u.roleId] || []).push(u); });

  return (
    <div className="space-y-6">
      <PageHeader
        title="Quản lý nhân sự"
        description="Danh sách nhân viên theo vai trò nghiệp vụ"
        icon={<Users className="h-5 w-5" />}
        actions={<Button onClick={() => setShowCreate(!showCreate)} className="gap-2"><UserPlus className="h-4 w-4" /> Tạo nhân viên</Button>}
      />

      {/* Create staff form */}
      {showCreate && (
        <Card className="border-primary/30 animate-fade-in-up">
          <CardHeader>
            <CardTitle className="flex items-center justify-between text-base">
              <span className="flex items-center gap-2"><UserPlus className="h-4 w-4" /> Tạo tài khoản nhân viên nội bộ</span>
              <button onClick={() => setShowCreate(false)} className="text-muted-foreground hover:text-foreground"><X className="h-4 w-4" /></button>
            </CardTitle>
          </CardHeader>
          <CardContent>
            <form onSubmit={handleCreate} className="space-y-3">
              <div className="grid gap-3 sm:grid-cols-2">
                <div className="space-y-2">
                  <Label>Họ và tên *</Label>
                  <Input value={createForm.name} onChange={(e) => setCreateForm({ ...createForm, name: e.target.value })} placeholder="Nguyễn Văn B" required />
                </div>
                <div className="space-y-2">
                  <Label>Email *</Label>
                  <Input type="email" value={createForm.email} onChange={(e) => setCreateForm({ ...createForm, email: e.target.value })} placeholder="email@example.com" required />
                </div>
              </div>
              <div className="grid gap-3 sm:grid-cols-2">
                <div className="space-y-2">
                  <Label>Số điện thoại *</Label>
                  <Input value={createForm.phone} onChange={(e) => setCreateForm({ ...createForm, phone: e.target.value })} placeholder="0901 234 567" required />
                </div>
                <div className="space-y-2">
                  <Label>Vai trò nội bộ *</Label>
                  <select value={createForm.roleId} onChange={(e) => setCreateForm({ ...createForm, roleId: e.target.value })} className="flex h-10 w-full rounded-md border border-input bg-background px-3 text-sm">
                    {STAFF_ROLES.map((r) => <option key={r.id} value={r.id}>{r.label}</option>)}
                  </select>
                </div>
              </div>
              <div className="space-y-2">
                <Label>Mật khẩu *</Label>
                <Input type="password" minLength={8} value={createForm.password} onChange={(e) => setCreateForm({ ...createForm, password: e.target.value })} required />
              </div>
              <div className="flex justify-end gap-2">
                <Button type="button" variant="outline" onClick={() => setShowCreate(false)}>Hủy</Button>
                <Button type="submit" disabled={createLoading} className="gap-2">
                  {createLoading ? <><Loader2 className="h-4 w-4 animate-spin" /> Đang tạo...</> : <><UserPlus className="h-4 w-4" /> Tạo tài khoản</>}
                </Button>
              </div>
            </form>
          </CardContent>
        </Card>
      )}

      {Object.entries(byRole).map(([roleId, list]) => (
        <Card key={roleId}>
          <CardHeader>
            <CardTitle className="flex items-center gap-2 text-base">
              <Badge variant="outline" className="bg-primary/5">{ROLE_LABELS[roleId]}</Badge>
              <span className="text-sm text-muted-foreground">{list.length} người</span>
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">
              {list.map((u) => (
                <div key={u.userId} className="rounded-lg border border-border p-4">
                  <div className="flex items-center gap-3">
                    <Avatar className="h-10 w-10 border border-border">
                      <AvatarFallback className="bg-primary/10 text-xs font-bold text-primary">
                        {u.name.split(" ").map((w: string) => w[0]).slice(0, 2).join("")}
                      </AvatarFallback>
                    </Avatar>
                    <div className="min-w-0">
                      <p className="text-sm font-semibold truncate">{u.name}</p>
                      <p className="text-xs text-muted-foreground">{ROLE_LABELS[u.roleId]}</p>
                    </div>
                  </div>
                  <div className="mt-3 space-y-1.5 text-xs text-muted-foreground">
                    <p className="flex items-center gap-2"><Mail className="h-3.5 w-3.5" /> <span className="truncate">{u.email}</span></p>
                    {u.phoneNumber && <p className="flex items-center gap-2"><Phone className="h-3.5 w-3.5" /> {u.phoneNumber}</p>}
                    {u.organizationName && <p className="flex items-center gap-2"><Building2 className="h-3.5 w-3.5" /> {u.organizationName}</p>}
                  </div>
                </div>
              ))}
            </div>
          </CardContent>
        </Card>
      ))}
    </div>
  );
}
